"""Module for the setting the static route on VDU using the admin cli for the VDU"""
import logging
import json
from taf.collectors.core.entities.managed_vdu_connection import ManagedVduConnection

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class VduStaticRouteSetter:
    """Sets the static route for emil log collection on a VDU component via admin cli"""

    def __init__(self, admin_params):
        """Construction for static route setting

        :param admin_params: Dictionary containing the connection details for admin cli
        """
        self.vdu_connection = ManagedVduConnection(vdu_connection_params=admin_params)

    def _create_delta_file(self, dest_ip_addr, gateway):

        parameters = [{'parameterName': 'staticRoutes',
                       'value': [{'destIpAddr': dest_ip_addr,
                                  'destinationIpPrefixLength': '32',
                                  'gateway': gateway,
                                  'preference': '1'}],
                       'operation': 'create'}]

        return [{'distName': 'MRBTS-1/TNLSVC-1/TNL-3/IPNO-1/IPRT-1',
                 'operation': 'create',
                 'parameters': parameters}]

    def set_static_route(self, dest_ip_addr, gateway, timeout=120):
        """ Sets a static route on the VDU.

        :param dest_ip_addr: the destination addres to route to
        :param gateway: the gateway to use for routing
        """
        try:
            self.vdu_connection.setup()

            delta = self._create_delta_file(dest_ip_addr=dest_ip_addr, gateway=gateway)
            response = self.vdu_connection.perform_delta_recommissioning(delta_file=json.dumps(delta), timeout=timeout)
            if response['status'] != 'success':
                logger.error('Error during setting static route oon VDU for uplane trace %s' % response)

        except Exception as e:
            logger.error("Exception during static route commissioning: %s" % e)
        finally:
            self.vdu_connection.teardown()
